from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MIGRATION = ROOT / "src/lib/clara-financial-context-migration.js"
WORKFLOW = ROOT / ".github/workflows/means-authority-verification.yml"
TEST = ROOT / "tests/device-transfer-stale-financial-authority.test.mjs"


def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly one match, found {count}")
    return text.replace(old, new, 1)


text = MIGRATION.read_text(encoding="utf-8")

anchor = '''const money = (value) => Math.max(0, signed(value));\n'''
insert = '''const money = (value) => Math.max(0, signed(value));\n\nfunction debtPaymentHistory(record = {}) {\n  const rows = Array.isArray(record?.paymentHistory)\n    ? record.paymentHistory\n    : Array.isArray(record?.payment_history)\n      ? record.payment_history\n      : [];\n  return rows.filter(Boolean);\n}\n\nfunction debtRecordId(record = {}) {\n  return text(record?.id || record?.debtId || record?.debt_id || record?.obligationId || record?.obligation_id);\n}\n\nfunction legacyPaymentStoredDueDate(payment = {}) {\n  return dateKey(payment?.dueDate || payment?.due_date);\n}\n\nfunction legacyPaymentActualDate(payment = {}) {\n  return dateKey(\n    payment?.actualPaymentDate ||\n      payment?.actual_payment_date ||\n      payment?.paymentDate ||\n      payment?.payment_date ||\n      payment?.paidAt ||\n      payment?.paid_at ||\n      payment?.recordedAt ||\n      payment?.recorded_at ||\n      payment?.createdAt ||\n      payment?.created_at\n  );\n}\n\n/**\n * Evidence for one narrowly-defined authority upgrade: older CLARA builds could store\n * a legacy_mark_paid Debt / Obligation payment against a future due occurrence. The\n * current authority remaps only that historical shape to the latest active occurrence\n * on or before the actual payment date. This helper proves the exact active-cycle plan\n * amount whose old derived snapshot can legitimately differ after a transfer.\n */\nexport function buildLegacyFutureDebtMigrationCompatibility(\n  debtRecords = [],\n  requirements = [],\n  epsilon = CLARA_FINANCIAL_RECONCILIATION_EPSILON\n) {\n  const affected = new Map();\n\n  (Array.isArray(debtRecords) ? debtRecords : []).forEach((record) => {\n    if (record?.deletedAt || record?.deleted_at) return;\n    const recordId = debtRecordId(record);\n    if (!recordId) return;\n\n    const debtRequirements = (Array.isArray(requirements) ? requirements : [])\n      .filter(\n        (entry) =>\n          lower(entry?.sourceType || entry?.kind) === "debt" &&\n          text(entry?.sourceId) === recordId &&\n          dateKey(entry?.date)\n      )\n      .sort((left, right) => dateKey(left?.date).localeCompare(dateKey(right?.date)));\n    if (debtRequirements.length === 0) return;\n\n    debtPaymentHistory(record).forEach((payment) => {\n      if (lower(payment?.source) !== "legacy_mark_paid") return;\n      const storedDueDate = legacyPaymentStoredDueDate(payment);\n      const actualDate = legacyPaymentActualDate(payment);\n      if (!storedDueDate || !actualDate || storedDueDate <= actualDate) return;\n\n      const intended = [...debtRequirements]\n        .reverse()\n        .find((entry) => dateKey(entry?.date) <= actualDate);\n      if (!intended) return;\n\n      const plannedAmount = money(intended?.plannedAmount);\n      const remainingAmount = money(intended?.remainingAmount);\n      const fulfilledAmount = money(intended?.fulfilledAmount);\n      if (!(plannedAmount > epsilon)) return;\n      if (remainingAmount > epsilon || fulfilledAmount + epsilon < plannedAmount) return;\n\n      const key = text(intended?.requirementKey) || `${recordId}:${dateKey(intended?.date)}`;\n      affected.set(key, plannedAmount);\n    });\n  });\n\n  if (affected.size === 0) return null;\n  return {\n    code: "legacy_future_debt_occurrence_authority_upgrade",\n    affectedRequirementCount: affected.size,\n    affectedPlanAmount: [...affected.values()].reduce((sum, amount) => sum + amount, 0),\n  };\n}\n'''
text = replace_once(text, anchor, insert, "insert debt compatibility helper")

old_imports = '''  const [meansAuthority, financeRepository, financialEngine] = await Promise.all([\n    import("./clara-means-authority.js"),\n    import("./financeRepository.js"),\n    import("../utils/financialEngine.js"),\n  ]);\n'''
new_imports = '''  const [meansAuthority, financeRepository, financialEngine, localFinanceStore] = await Promise.all([\n    import("./clara-means-authority.js"),\n    import("./financeRepository.js"),\n    import("../utils/financialEngine.js"),\n    import("./localFinanceStore.js"),\n  ]);\n'''
text = replace_once(text, old_imports, new_imports, "load local finance store")

old_load = '''  const [canonical, wallets, walletTransactions, transfers, savingsGoals, emergencyFund] =\n    await Promise.all([\n      meansAuthority.buildCanonicalMeansSnapshot({ profile: scopedProfile, now }),\n      financeRepository.getWallets(owner).catch(() => []),\n      financeRepository.getWalletTransactions(owner).catch(() => []),\n      financeRepository.getTransfers(owner).catch(() => []),\n      financeRepository.getSavingsGoals(owner).catch(() => []),\n      financeRepository.getEmergencyFund(owner).catch(() => null),\n    ]);\n'''
new_load = '''  const [\n    canonical,\n    wallets,\n    walletTransactions,\n    transfers,\n    savingsGoals,\n    emergencyFund,\n    privatePreferences,\n  ] = await Promise.all([\n    meansAuthority.buildCanonicalMeansSnapshot({ profile: scopedProfile, now }),\n    financeRepository.getWallets(owner).catch(() => []),\n    financeRepository.getWalletTransactions(owner).catch(() => []),\n    financeRepository.getTransfers(owner).catch(() => []),\n    financeRepository.getSavingsGoals(owner).catch(() => []),\n    financeRepository.getEmergencyFund(owner).catch(() => null),\n    localFinanceStore\n      .getLocalRecordsByUser(localFinanceStore.LOCAL_FINANCE_STORES.privatePreferences, {\n        localUserId: owner,\n        includeDeleted: false,\n      })\n      .catch(() => []),\n  ]);\n'''
text = replace_once(text, old_load, new_load, "load transfer debt evidence")

old_requirements_end = '''  const availableWalletMoney = signed(\n    canonical?.availableWalletMoney ?? walletState.availableNow\n  );\n'''
new_requirements_end = '''  const legacyFutureDebtCompatibility = buildLegacyFutureDebtMigrationCompatibility(\n    (Array.isArray(privatePreferences) ? privatePreferences : []).filter((record) => {\n      const kind = lower(record?.recordKind || record?.recordType || record?.kind);\n      return kind === "debt_obligation";\n    }),\n    requirements\n  );\n\n  const availableWalletMoney = signed(\n    canonical?.availableWalletMoney ?? walletState.availableNow\n  );\n'''
text = replace_once(text, old_requirements_end, new_requirements_end, "derive compatibility evidence")

old_return_tail = '''    fulfillmentContext: requirements.map((entry) => ({\n      requirementKey: entry.requirementKey,\n      fulfilledAmount: entry.fulfilledAmount,\n    })),\n  };\n}\n'''
new_return_tail = '''    fulfillmentContext: requirements.map((entry) => ({\n      requirementKey: entry.requirementKey,\n      fulfilledAmount: entry.fulfilledAmount,\n    })),\n    compatibilityEvidence: {\n      legacyFutureDebtOccurrence: legacyFutureDebtCompatibility,\n    },\n  };\n}\n'''
text = replace_once(text, old_return_tail, new_return_tail, "persist compatibility evidence")

old_status = '''  const allMatch = Object.values(reconciliation).every(Boolean);\n  const status = unresolvedItems.length > 0 ? "unresolved" : allMatch ? "success" : "failed";\n\n  return {\n    status,\n    migrationVersion: CLARA_FINANCIAL_CONTEXT_MIGRATION_VERSION,\n    sourceVaultId,\n    destinationVaultId,\n    reconciliation,\n    diagnostics: {\n'''
new_status = '''  const allMatch = Object.values(reconciliation).every(Boolean);\n  const legacyFutureDebtEvidence =\n    destination?.compatibilityEvidence?.legacyFutureDebtOccurrence || null;\n  const staleAuthorityPlanDelta =\n    money(source?.remainingPlannedSpending) - money(destination?.remainingPlannedSpending);\n  const legacyFutureDebtAuthorityUpgradeMatch = Boolean(\n    unresolvedItems.length === 0 &&\n      !allMatch &&\n      reconciliation.cycleMatch &&\n      reconciliation.walletMatch &&\n      reconciliation.anchorMatch &&\n      !reconciliation.remainingPlanMatch &&\n      staleAuthorityPlanDelta > epsilon &&\n      money(legacyFutureDebtEvidence?.affectedPlanAmount) > epsilon &&\n      equalNumber(\n        staleAuthorityPlanDelta,\n        legacyFutureDebtEvidence?.affectedPlanAmount,\n        epsilon\n      )\n  );\n  const status =\n    unresolvedItems.length > 0\n      ? "unresolved"\n      : allMatch || legacyFutureDebtAuthorityUpgradeMatch\n        ? "success"\n        : "failed";\n  const compatibilityAdjustment = legacyFutureDebtAuthorityUpgradeMatch\n    ? {\n        code: legacyFutureDebtEvidence.code,\n        affectedRequirementCount: legacyFutureDebtEvidence.affectedRequirementCount,\n        affectedPlanAmount: legacyFutureDebtEvidence.affectedPlanAmount,\n        sourceRemainingPlannedSpending: money(source?.remainingPlannedSpending),\n        destinationRemainingPlannedSpending: money(destination?.remainingPlannedSpending),\n      }\n    : null;\n\n  return {\n    status,\n    migrationVersion: CLARA_FINANCIAL_CONTEXT_MIGRATION_VERSION,\n    sourceVaultId,\n    destinationVaultId,\n    reconciliation,\n    compatibilityAdjustment,\n    diagnostics: {\n'''
text = replace_once(text, old_status, new_status, "add strict stale authority compatibility")

old_diag_tail = '''      destinationReportedMeansScoreMatchesDerived: equalNullableNumber(\n        destination.meansScore,\n        destinationDerived.meansScore,\n        epsilon\n      ),\n    },\n'''
new_diag_tail = '''      destinationReportedMeansScoreMatchesDerived: equalNullableNumber(\n        destination.meansScore,\n        destinationDerived.meansScore,\n        epsilon\n      ),\n      legacyFutureDebtAuthorityPlanDelta: staleAuthorityPlanDelta,\n      legacyFutureDebtAuthorityUpgradeMatch,\n    },\n'''
text = replace_once(text, old_diag_tail, new_diag_tail, "extend diagnostics")

MIGRATION.write_text(text, encoding="utf-8")

workflow = WORKFLOW.read_text(encoding="utf-8")
workflow_anchor = '''          node --test tests/device-transfer-historical-identity-scope.test.mjs\n'''
workflow_insert = '''          node --test tests/device-transfer-historical-identity-scope.test.mjs\n          node --test tests/device-transfer-stale-financial-authority.test.mjs\n'''
workflow = replace_once(workflow, workflow_anchor, workflow_insert, "register transfer compatibility regression")
WORKFLOW.write_text(workflow, encoding="utf-8")

TEST.write_text(r'''import test from "node:test";\nimport assert from "node:assert/strict";\n\nimport {\n  buildLegacyFutureDebtMigrationCompatibility,\n  reconcileFinancialContextMigration,\n} from "../src/lib/clara-financial-context-migration.js";\n\nconst cycle = {\n  sourceId: "income-master",\n  cycleStart: "2026-09-20",\n  cycleEnd: "2026-10-05",\n};\n\nfunction snapshot({ remainingPlannedSpending, compatibilityEvidence = undefined } = {}) {\n  const availableWalletMoney = 5000;\n  const cycle100Anchor = 5000;\n  const wallBill = availableWalletMoney - remainingPlannedSpending;\n  return {\n    migrationVersion: 1,\n    localVaultId: "vault",\n    activeCycle: cycle,\n    availableWalletMoney,\n    remainingPlannedSpending,\n    cycle100Anchor,\n    anchorState: "anchored",\n    wallBill,\n    meansScore: Math.round(100 + ((wallBill / cycle100Anchor) * 100)),\n    compatibilityEvidence,\n  };\n}\n\ntest("legacy future-due Debt authority drift is accepted only for its exact proven plan delta", () => {\n  const debtId = "transfer:destination:debt-1";\n  const requirements = [\n    {\n      requirementKey: `debt:${debtId}:2026-09-25`,\n      sourceType: "debt",\n      sourceId: debtId,\n      date: "2026-09-25",\n      plannedAmount: 1500,\n      fulfilledAmount: 1500,\n      remainingAmount: 0,\n    },\n  ];\n  const evidence = buildLegacyFutureDebtMigrationCompatibility(\n    [\n      {\n        id: debtId,\n        recordKind: "debt_obligation",\n        paymentHistory: [\n          {\n            id: "legacy-payment",\n            source: "legacy_mark_paid",\n            amount: 1500,\n            dueDate: "2026-10-25",\n            actualPaymentDate: "2026-09-26",\n          },\n        ],\n      },\n    ],\n    requirements\n  );\n\n  assert.deepEqual(evidence, {\n    code: "legacy_future_debt_occurrence_authority_upgrade",\n    affectedRequirementCount: 1,\n    affectedPlanAmount: 1500,\n  });\n\n  const result = reconcileFinancialContextMigration({\n    source: snapshot({ remainingPlannedSpending: 1500 }),\n    destination: snapshot({\n      remainingPlannedSpending: 0,\n      compatibilityEvidence: { legacyFutureDebtOccurrence: evidence },\n    }),\n    unresolved: [],\n  });\n\n  assert.equal(result.status, "success");\n  assert.equal(result.reconciliation.remainingPlanMatch, false);\n  assert.equal(result.compatibilityAdjustment?.code, "legacy_future_debt_occurrence_authority_upgrade");\n  assert.equal(result.compatibilityAdjustment?.affectedPlanAmount, 1500);\n});\n\ntest("generic Remaining Plan mismatch stays fail-closed without proven legacy debt evidence", () => {\n  const result = reconcileFinancialContextMigration({\n    source: snapshot({ remainingPlannedSpending: 1500 }),\n    destination: snapshot({ remainingPlannedSpending: 0 }),\n    unresolved: [],\n  });\n  assert.equal(result.status, "failed");\n  assert.equal(result.compatibilityAdjustment, null);\n});\n\ntest("legacy debt evidence cannot authorize a different financial delta", () => {\n  const evidence = {\n    code: "legacy_future_debt_occurrence_authority_upgrade",\n    affectedRequirementCount: 1,\n    affectedPlanAmount: 1500,\n  };\n  const result = reconcileFinancialContextMigration({\n    source: snapshot({ remainingPlannedSpending: 2000 }),\n    destination: snapshot({\n      remainingPlannedSpending: 0,\n      compatibilityEvidence: { legacyFutureDebtOccurrence: evidence },\n    }),\n    unresolved: [],\n  });\n  assert.equal(result.status, "failed");\n  assert.equal(result.compatibilityAdjustment, null);\n});\n'''.replace('\\n', '\n'), encoding="utf-8")

print("Applied strict Device Transfer stale-financial-authority compatibility patch.")
